        },
        {
            "contains_type": [
                "*"
            ],
            "data_path": "*.indicator_tags",
            "description": "List of tags associated with the indicator record"
        },
        {
            "contains_type": [],
            "data_path": "*.indicator_cef_type",
            "description": "List of cef types associated with the indicator record"
        }
    ],
